import React from 'react';
import {renderToStaticMarkup} from 'react-dom/server';
import {afterEach,describe,expect,it,vi} from 'vitest';
import type {CmnReadingQuery} from '../shared/cmn-reading';
import fixtures from '../../tests/fixtures/cmn-reading-query-m141.json';
import {CmnReadingContent,CmnReadingView,createCmnReadingController,loadCmnReadingOptions} from './CmnReadingView';

/** These five DTOs were generated by D04's actual pinned adapter;no meanings are invented here. */
const query=(char:string)=>structuredClone(fixtures.queries.find(q=>q.char===char)) as unknown as CmnReadingQuery;
const ready=(char:string,pinyin=query(char).currentDefault?.pinyin??'未记录')=>renderToStaticMarkup(<CmnReadingContent char={char} currentPinyin={pinyin} state={{expanded:true,phase:'ready',query:query(char)}} onRetry={()=>{}}/>);
const deferred=<T,>()=>{let resolve!:(v:T)=>void,reject!:(e:Error)=>void;const promise=new Promise<T>((ok,no)=>{resolve=ok;reject=no;});return{promise,resolve,reject};};
const active=(char:string,loader:(c:string)=>Promise<CmnReadingQuery>)=>{const controller=createCmnReadingController(char,loader);controller.activate();return controller;};
afterEach(()=>vi.unstubAllGlobals());

describe('read-only Mandarin dictionary browser using real fixed-source DTOs',()=>{
 it('does not request data before opening the native disclosure',()=>{
  const loader=vi.fn(async()=>query('长'));
  const html=renderToStaticMarkup(<CmnReadingView char="长" currentPinyin="zhǎng" getOptions={loader}/>);
  expect(html).toContain('其他读音与义项');expect(html).toContain('<details');expect(html).toContain('<summary');expect(loader).not.toHaveBeenCalled();
 });
 it('keeps the saved name reading separate from the real dictionary default and all three source readings',()=>{
  const html=ready('长','zhǎng');
  for(const text of ['cháng','zhàng','zhǎng','本名采用','字库默认读音','姓名原字','词典字形','与本名读音相同'])expect(html).toContain(text);
  expect(html.match(/与本名读音相同/g)).toHaveLength(1);
  expect(html).not.toMatch(/type="(?:radio|checkbox)"|<select|确认并保存|采用此读音/);
  expect(html).toContain('浏览不会更改名字读音或评分');
 });
 it('renders every original definition, quotation and example without changing fixture bytes',()=>{
  const q=query('长'),before=JSON.stringify(q),html=renderToStaticMarkup(<CmnReadingContent char="长" currentPinyin="cháng" state={{expanded:true,phase:'ready',query:q}} onRetry={()=>{}}/>),escape=(s:string)=>renderToStaticMarkup(<span>{s}</span>).slice(6,-7);
  for(const option of q.options)for(const definition of option.definitions){expect(html).toContain(escape(definition.original.def));for(const text of [...definition.original.quote??[],...definition.original.example??[],...definition.original.link??[]])expect(html).toContain(escape(text));}
  expect(JSON.stringify(q)).toBe(before);
 });
 it('retains reference-only senses within the four real readings of 行 without expanding a cited term',()=>{
  const html=ready('行');
  for(const text of ['xíng','háng','xìng','hàng','參見「行行」、「樹行子」等條。'])expect(html).toContain(text);
  expect(html).toContain('词典参见（未展开所引词条）');expect(html).toContain('不据此补成独立字义');
 });
 it('puts 沈’s real unparsed chén reference in a separate nonselectable source disclosure',()=>{
  const q=query('沈'),html=ready('沈');
  expect(q.status).toBe('available');expect(q.options.map(o=>o.pinyin)).toEqual(['shěn']);expect(q.references).toHaveLength(1);
  expect(html).toContain('仅供核对的原始参见资料');expect(html).toContain('不作为可采用的读音或义项');expect(html.match(/class="cmn-reading-option"/g)).toHaveLength(1);
 });
 it('distinguishes real unknown-character and missing-source-identity cases',()=>{
  const missing=ready('燚'),unknown=ready('重');
  expect(missing).toContain('没有能与本版词典核对的读音身份');expect(unknown).toContain('不在这批固定字库');
  for(const html of[missing,unknown]){expect(html).toContain('不补造备选读音');expect(html).not.toContain('class="cmn-reading-option"');}
 });
 it('covers the whole-query reference-only contract as an explicitly synthetic boundary,not an observed source case',()=>{
  const synthetic={...query('沈'),status:'reference-only' as const,options:[],defaultOptionIds:[]};
  const html=renderToStaticMarkup(<CmnReadingContent char="沈" currentPinyin="shěn" state={{expanded:true,phase:'ready',query:synthetic}} onRetry={()=>{}}/>);
  expect(html).toContain('没有可直接浏览的独立读音义项');expect(html).not.toContain('class="cmn-reading-option"');
 });
 it('keeps complete source anchors accessible behind native details',()=>{
  const q=query('行'),html=ready('行');
  for(const text of[q.source.commit,q.source.rawSha256,q.source.profileSha256,q.options[0].entry.path,q.options[0].entry.sha256,q.options[0].heteronym.path,q.options[0].heteronym.sha256,q.options[0].definitions[0].definitionId,'CC-BY-ND-3.0-TW','查看此读音的完整来源'])expect(html).toContain(text);
 });
 it('escapes raw dictionary and reference text',()=>{
  const q=query('长');q.options[0].definitions[0].original.def='<img src=x onerror=evil()>';const html=renderToStaticMarkup(<CmnReadingContent char="长" currentPinyin="cháng" state={{expanded:true,phase:'ready',query:q}} onRetry={()=>{}}/>);
  expect(html).toContain('&lt;img');expect(html).not.toContain('<img');
 });
 it('shows loading and recoverable read failure states without inventing source options',()=>{
  for(const phase of['loading','error'] as const){const html=renderToStaticMarkup(<CmnReadingContent char="长" currentPinyin="cháng" state={{expanded:true,phase}} onRetry={()=>{}}/>);expect(html).not.toContain('class="cmn-reading-option"');expect(html).toContain(phase==='loading'?'role="status"':'role="alert"');if(phase==='error')expect(html).toContain('重新读取词典资料');}
 });
 it('refuses to display an old character query even if handed mismatched presentation state',()=>{
  const html=renderToStaticMarkup(<CmnReadingContent char="行" currentPinyin="xíng" state={{expanded:true,phase:'ready',query:query('长')}} onRetry={()=>{}}/>);
  expect(html).not.toContain('cháng');expect(html).not.toContain('class="cmn-reading-option"');
 });
});
describe('actual asynchronous viewer controller',()=>{
 it('loads once when opened and not again for a repeated opening event',async()=>{
  const request=deferred<CmnReadingQuery>(),loader=vi.fn(()=>request.promise),c=active('长',loader);
  expect(loader).not.toHaveBeenCalled();const opening=c.setExpanded(true);await c.setExpanded(true);expect(c.getSnapshot().phase).toBe('loading');expect(loader).toHaveBeenCalledTimes(1);
  request.resolve(query('长'));await opening;expect(c.getSnapshot().phase).toBe('ready');await c.setExpanded(false);await c.setExpanded(true);expect(loader).toHaveBeenCalledTimes(1);c.dispose();
 });
 it('ignores a closed request arriving after a new opening has started',async()=>{
  const first=deferred<CmnReadingQuery>(),second=deferred<CmnReadingQuery>(),loader=vi.fn().mockReturnValueOnce(first.promise).mockReturnValueOnce(second.promise),c=active('长',loader),a=c.setExpanded(true);
  await c.setExpanded(false);const b=c.setExpanded(true);first.resolve(query('长'));await a;expect(c.getSnapshot().phase).toBe('loading');second.resolve(query('长'));await b;expect(c.getSnapshot().phase).toBe('ready');c.dispose();
 });
 it('prevents a switched-away character’s late response from affecting the new viewer',async()=>{
  const late=deferred<CmnReadingQuery>(),old=active('长',()=>late.promise),pending=old.setExpanded(true);old.dispose();
  const current=active('行',async()=>query('行'));await current.setExpanded(true);const snapshot=current.getSnapshot();late.resolve(query('长'));await pending;
  expect(current.getSnapshot()).toBe(snapshot);expect(snapshot.query?.char).toBe('行');expect(old.getSnapshot().query).toBeUndefined();current.dispose();
 });
 it('recovers after a real API-style rejection and rejects a wrong-character response',async()=>{
  const loader=vi.fn().mockRejectedValueOnce(new Error(fixtures.apiErrors.sourceUnavailable)).mockResolvedValueOnce(query('行')).mockResolvedValueOnce(query('长')),c=active('长',loader);
  await c.setExpanded(true);expect(c.getSnapshot().phase).toBe('error');await c.retry();expect(c.getSnapshot().phase).toBe('error');await c.retry();expect(c.getSnapshot().query?.char).toBe('长');c.dispose();
 });
 it('does not commit after disposal and can reactivate safely during StrictMode effect replay',async()=>{
  const first=deferred<CmnReadingQuery>(),second=deferred<CmnReadingQuery>(),loader=vi.fn().mockReturnValueOnce(first.promise).mockReturnValueOnce(second.promise),c=active('长',loader),pending=c.setExpanded(true);c.dispose();c.activate();first.resolve(query('长'));await pending;expect(c.getSnapshot().phase).toBe('loading');second.resolve(query('长'));await second.promise;await Promise.resolve();expect(c.getSnapshot().phase).toBe('ready');c.dispose();
 });
 it('calls the real product API global and exposes no name mutation operation',async()=>{
  const q=query('长'),read=vi.fn(async()=>q),write=vi.fn(()=>{throw new Error('must not mutate');});vi.stubGlobal('window',{studio:{getCmnReadingOptions:read,saveSession:write}});
  expect(await loadCmnReadingOptions('长')).toBe(q);expect(read).toHaveBeenCalledWith('长');expect(write).not.toHaveBeenCalled();
  vi.stubGlobal('window',{studio:{}});await expect(loadCmnReadingOptions('长')).rejects.toThrow('尚未连接');
 });
});
